//! The media matrix.
//!
//! `docs/MEDIA-MATRIX.md` is generated from `lab_core::reducer::TIERS`, never
//! hand-edited. `--check` regenerates the document in memory and compares it to
//! the file on disk, so the docs cannot claim a tier is finished when it is not.

use std::fmt::Write as _;

use lab_core::reducer::{State, TIERS};

/// The exact document written to `docs/MEDIA-MATRIX.md`.
pub fn render() -> String {
    let mut out = String::new();

    out.push_str("# Medium matrix\n\n");
    out.push_str(
        "Generated by `cargo xtask matrix`. Do not edit by hand: change\n\
         `crates/lab-core/src/reducer.rs` and regenerate.\n\n",
    );
    out.push_str(
        "Every medium is reduced to an N x N grid of RGB cells and then goes through\n\
         the identical solver. A tier is only `ok` when a reducer exists *and* the CLI\n\
         can run it.\n\n",
    );

    out.push_str("| tier | id | state | extensions | reduction |\n");
    out.push_str("| --- | --- | --- | --- | --- |\n");
    for spec in TIERS {
        let exts = spec
            .extensions
            .iter()
            .map(|e| format!("`.{e}`"))
            .collect::<Vec<_>>()
            .join(" ");
        let _ = writeln!(
            out,
            "| `{}` | `{}` | `{}` | {} | {} |",
            spec.tier.label(),
            spec.tier.id(),
            spec.state.glyph(),
            exts,
            spec.tier.reduction()
        );
    }

    out.push_str("\n## State legend\n\n");
    out.push_str("| state | meaning |\n| --- | --- |\n");
    out.push_str("| `ok` | reducer exists and the CLI runs it |\n");
    out.push_str("| `wip` | reducer exists but is not wired into the CLI |\n");
    out.push_str("| `--` | designed only; no reducer yet |\n");

    let shipped = TIERS.iter().filter(|s| s.state == State::Shipped).count();
    let total = TIERS.len();
    let _ = writeln!(
        out,
        "\n{shipped} of {total} tiers are `ok`; the rest fail loudly with \
         `not implemented` rather than substituting a different medium."
    );

    out
}

/// Compare the on-disk document with the generated one.
///
/// `Ok(String::new())` when they match; otherwise the message explaining what
/// changed, ready to print.
pub fn check_on_disk(root: &std::path::Path) -> Result<(), String> {
    let path = root.join("docs").join("MEDIA-MATRIX.md");
    let generated = render();

    match std::fs::read_to_string(&path) {
        Ok(on_disk) if on_disk == generated => Ok(()),
        Ok(_) => Err(format!(
            "{} is out of date. Run `cargo xtask matrix` to regenerate it.",
            path.display()
        )),
        Err(e) => Err(format!(
            "could not read {}: {e}. Run `cargo xtask matrix` to create it.",
            path.display()
        )),
    }
}
